/// <summary>
/// The <c>AVAInventUpd_RegisteredCls_Extension</c> represents a extension of the class InventUpd_Registered
/// </summary>
[
    ExtensionOf(classStr(InventUpd_Registered))
]
final class AVAInventUpd_RegisteredCls_Extension
{
}

Method.Source:
/// <summary>
/// Extension Methode for initUpdate()
/// </summary>
protected void initUpdate()
{
    next initUpdate();

    this.avaInitUpdate_registerDimId();
}

/// <summary>
/// Update the registerDimId with the new license plate id to register
/// </summary>
public void avaInitUpdate_registerDimId()
{
    InventDim                       avaRegisterDim;
    WHSLicensePlateId               avaLicensePlateToRegister;
    AVARegisterASNItemsIDisposable  avaRegisterASNItemsIDisposable;

    avaRegisterASNItemsIDisposable  = AVARegisterASNItemsIDisposable::current();

    if (avaRegisterASNItemsIDisposable
     && avaRegisterASNItemsIDisposable.aktiveProcess == NoYes::Yes)
    {
        avaLicensePlateToRegister   = avaRegisterASNItemsIDisposable.lastLicensePlateToRegister;
        avaRegisterDim              = InventDim::find(registerDimId);

        if (avaRegisterDim
         && avaLicensePlateToRegister
         && avaRegisterDim.LicensePlateId
         && avaRegisterDim.LicensePlateId == avaRegisterASNItemsIDisposable.loopUpLicensePlateToRegister(avaLicensePlateToRegister, false))
        {                
            avaRegisterDim.LicensePlateId = avaLicensePlateToRegister;

            registerDimId = InventDim::findOrCreate(avaRegisterDim).inventDimId;
        }
    }
}
